-- REPORT-006: generation receipts contain fingerprints and queries, never report contents or recipient credentials.
CREATE TABLE tt_report_schedules(id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('financial','rent_roll','delinquency','vacancy','maintenance')),property_id TEXT NOT NULL REFERENCES tt_properties(id),owner_id TEXT,basis TEXT NOT NULL CHECK(basis IN ('cash','accrual')),zone TEXT NOT NULL,starts TEXT NOT NULL,day_of_month INTEGER NOT NULL CHECK(day_of_month BETWEEN 1 AND 31),hour INTEGER NOT NULL CHECK(hour BETWEEN 0 AND 23),require_close INTEGER NOT NULL CHECK(require_close IN (0,1)),created_by TEXT NOT NULL,created_at TEXT NOT NULL,reference TEXT NOT NULL,retired_at TEXT);
CREATE TABLE tt_report_generations(id TEXT PRIMARY KEY,schedule_id TEXT NOT NULL REFERENCES tt_report_schedules(id),local_month TEXT NOT NULL,report_from TEXT NOT NULL,report_to TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('generated','held')),generation_version INTEGER NOT NULL DEFAULT 1,fingerprint TEXT,next_action TEXT NOT NULL,generated_at TEXT NOT NULL,UNIQUE(schedule_id,local_month));
CREATE TRIGGER tt_report_schedule_fixed BEFORE UPDATE OF name,kind,property_id,owner_id,basis,zone,starts,day_of_month,hour,require_close,created_by,created_at,reference ON tt_report_schedules BEGIN SELECT RAISE(ABORT,'Retire a schedule and create new reviewed terms'); END;
CREATE TRIGGER tt_report_generation_fixed BEFORE UPDATE ON tt_report_generations BEGIN SELECT RAISE(ABORT,'Generation receipts are immutable'); END;
